insert into public.reg_fields (id, module_id, label, what, io, status, confidence, why, help, where_subtab, facts, who, options, "when", how, source, missing_behavior, depends_on, feeds_into, note, sort_order, enabled, placement_tab, placement_area) values
  ('open.wants', 'opening_quiz', 'What do you want?', 'tap_multi', 'asks', 'live', null, null, 'Tap all that fit. There is no order yet, and you can change them later.', 'What you want', '["goals"]'::jsonb, '["player"]'::jsonb, '["Retire early","Retire on time","Get out of debt","Build a cushion","Buy a home","Travel more","Have or raise kids","Change careers or quit my job","Start a business","Give more","Just feel calm about money","Something else"]'::jsonb, '{"stage":"setup","step_number":1,"shown_if":"A new player who tapped Start. It is the first screen, before the four questions. \"Skip for now\" passes it."}'::jsonb, '"Chips, any number, no order. Each pick becomes a goal in c.goals (waiting on Someday) when the profile is made."'::jsonb, '{"file":"game/features/wants.js","lines":"30-78","raw":"game/features/wants.js:30-78"}'::jsonb, null, '[]'::jsonb, '["tab.goals","open.reveal"]'::jsonb, null, 10, true, 'Opening', 'What it is / What it could be'),
  ('open.wants_own', 'opening_quiz', 'Add my own', 'text', 'asks', 'live', null, null, null, 'What you want', '["goals"]'::jsonb, '["player"]'::jsonb, null, '{"stage":"setup","step_number":1,"shown_if":"Only after a tap on the chip \"Something else\"."}'::jsonb, '"One text box. The typed name becomes a goal of the kind \"Something else\"."'::jsonb, '{"file":"game/features/goalrank.js","lines":"118","raw":"game/features/goalrank.js:118"}'::jsonb, null, '["open.wants"]'::jsonb, '["tab.goals"]'::jsonb, null, 20, true, 'Opening', 'What it is / What it could be'),
  ('open.age', 'opening_quiz', 'How old are you?', 'range_chips', 'asks', 'live', null, null, 'A range is fine.', 'Question 1 of 4', '["age"]'::jsonb, '["player"]'::jsonb, '["Under 25","25 to 29","30 to 34","35 to 39","40 to 44","45 to 49","50 to 54","55 to 59","60 to 64","65 to 69","I know it"]'::jsonb, '{"stage":"setup","step_number":2,"shown_if":"After What you want (or Skip for now)."}'::jsonb, '"Range chips; the amount is the middle of the range and counts as a Guess. \"I know it\" opens one box to type the exact number (Exact)."'::jsonb, '{"file":"game/features/couldbe.js","lines":"139","raw":"game/features/couldbe.js:139"}'::jsonb, null, '["open.wants"]'::jsonb, '["open.top_is","open.top_could","calc.derive"]'::jsonb, null, 30, true, 'Opening', 'What it is / What it could be'),
  ('open.spend', 'opening_quiz', 'About how much do you spend in a month?', 'range_chips', 'asks', 'live', null, null, 'Everything that goes out: rent, food, bills, fun. A rough range is fine.', 'Question 2 of 4', '["spending","spending_rows","could_be_store"]'::jsonb, '["player"]'::jsonb, '["Under $2k","$2k to $3k","$3k to $4k","$4k to $5k","$5k to $7k","$7k to $10k","$10k or more","I know it","No idea, use typical"]'::jsonb, '{"stage":"setup","step_number":3,"shown_if":"After question 1 is answered."}'::jsonb, '"Range chips; the amount is the middle of the range and counts as a Guess. \"I know it\" opens one box to type the exact number (Exact). \"No idea, use typical\" fills a sourced typical value for the age, as a Guess."'::jsonb, '{"file":"game/features/couldbe.js","lines":"141","raw":"game/features/couldbe.js:141"}'::jsonb, null, '["open.age"]'::jsonb, '["open.top_is","open.top_could","calc.derive"]'::jsonb, null, 40, true, 'Opening', 'What it is / What it could be'),
  ('open.inv', 'opening_quiz', 'About how much do you have invested?', 'range_chips', 'asks', 'live', null, null, 'Retirement accounts and other investments together. Not your checking or savings.', 'Question 3 of 4', '["invested_total","investment_rows","could_be_store"]'::jsonb, '["player"]'::jsonb, '["Nothing yet","Under $10k","$10k to $50k","$50k to $100k","$100k to $250k","$250k to $500k","$500k to $1M","$1M or more","I know it","No idea, use typical"]'::jsonb, '{"stage":"setup","step_number":4,"shown_if":"After question 2 is answered."}'::jsonb, '"Range chips; the amount is the middle of the range and counts as a Guess. \"I know it\" opens one box to type the exact number (Exact). \"No idea, use typical\" fills a sourced typical value for the age, as a Guess."'::jsonb, '{"file":"game/features/couldbe.js","lines":"147","raw":"game/features/couldbe.js:147"}'::jsonb, null, '["open.spend"]'::jsonb, '["open.top_is","open.top_could","calc.derive"]'::jsonb, null, 50, true, 'Opening', 'What it is / What it could be'),
  ('open.save', 'opening_quiz', 'About how much do you save or invest in a month?', 'range_chips', 'asks', 'live', null, null, 'What is left after spending and goes into savings or investments.', 'Question 4 of 4', '["take_home","income_rows","invests","could_be_store"]'::jsonb, '["player"]'::jsonb, '["Nothing right now","Under $250","$250 to $500","$500 to $1k","$1k to $2k","$2k to $4k","$4k or more","I know it","No idea, use typical"]'::jsonb, '{"stage":"setup","step_number":5,"shown_if":"After question 3 is answered."}'::jsonb, '"Range chips; the amount is the middle of the range and counts as a Guess. \"I know it\" opens one box to type the exact number (Exact). \"No idea, use typical\" fills a sourced typical value for the age, as a Guess. Saved a month is not kept as its own number: it is added to spending to make the income row."'::jsonb, '{"file":"game/features/couldbe.js","lines":"153","raw":"game/features/couldbe.js:153"}'::jsonb, null, '["open.inv"]'::jsonb, '["open.top_is","open.top_could","calc.derive"]'::jsonb, null, 60, true, 'Opening', 'What it is / What it could be'),
  ('open.top_is', 'opening_quiz', 'What it is', 'computed', 'shows', 'live', null, null, null, 'Pinned at the top of every screen of the flow', '["spending","invested_total","age","could_be_store"]'::jsonb, '["player"]'::jsonb, null, '{"stage":"setup","step_number":null,"shown_if":"From the first screen of the flow on. Two big numbers at first, one slim strip from the first way screen on."}'::jsonb, '"The FI number the standard way (25 times a year of spending) and the age the investments reach it. Shows Guess, Close or Exact as a pill."'::jsonb, '{"file":"game/features/couldbe.js","lines":"954","raw":"game/features/couldbe.js:954"}'::jsonb, '"Shows \"No number yet\" and, for the age, \"not at this pace yet\"."'::jsonb, '["open.age","open.spend","open.inv","open.save"]'::jsonb, '["home.cb_tile"]'::jsonb, null, 70, true, 'Opening', 'What it is / What it could be'),
  ('open.top_could', 'opening_quiz', 'What it could be', 'computed', 'shows', 'live', null, null, null, 'Pinned at the top of every screen of the flow', '["could_be_store","spending","invested_total","age"]'::jsonb, '["player"]'::jsonb, null, '{"stage":"setup","step_number":null,"shown_if":"Same as What it is. The two are equal until the player counts something."}'::jsonb, '"The same number after the things the player counted (the ways). Under it: \"The two are equal until you count something.\""'::jsonb, '{"file":"game/features/couldbe.js","lines":"965","raw":"game/features/couldbe.js:965"}'::jsonb, '"Shows \"No number yet\"."'::jsonb, '["open.top_is"]'::jsonb, '["home.cb_tile","open.reveal"]'::jsonb, null, 80, true, 'Opening', 'What it is / What it could be'),
  ('open.way_shape', 'opening_ways', 'Spending eases as you age', 'tap_single', 'asks', 'live', null, null, null, 'Way 1 of 5', '["could_be_store"]'::jsonb, '["player"]'::jsonb, '["Count this","Already doing it","Not for me"]'::jsonb, '{"stage":"setup","step_number":7,"shown_if":"After the chart. A way that does not apply to the player says so."}'::jsonb, '"Three buttons. \"Count this\" lowers What it could be and shows a receipt (dollars off the target, months sooner)."'::jsonb, '{"file":"game/features/couldbe.js","lines":"77","raw":"game/features/couldbe.js:77"}'::jsonb, null, '["open.top_is"]'::jsonb, '["open.top_could"]'::jsonb, null, 90, true, 'Opening', 'What it is / What it could be'),
  ('open.way_ss', 'opening_ways', 'Social Security pays part of it', 'tap_single', 'asks', 'live', null, null, null, 'Way 2 of 5', '["could_be_store"]'::jsonb, '["player"]'::jsonb, '["Count this","Already doing it","Not for me"]'::jsonb, '{"stage":"setup","step_number":8,"shown_if":"After the chart. A way that does not apply to the player says so."}'::jsonb, '"Three buttons. \"Count this\" lowers What it could be and shows a receipt (dollars off the target, months sooner)."'::jsonb, '{"file":"game/features/couldbe.js","lines":"83","raw":"game/features/couldbe.js:83"}'::jsonb, null, '["open.top_is"]'::jsonb, '["open.top_could"]'::jsonb, null, 100, true, 'Opening', 'What it is / What it could be'),
