  ('setup.accts', 'setup_assets', 'Where your money lives', 'tap_multi', 'asks', 'live', null, null, 'Tap every kind of account you have. If none, just tap Next.', 'Where your money lives', '["account_kinds"]'::jsonb, '["player"]'::jsonb, '["Checking","Savings","Cash at home","401(k) or work plan","IRA","Roth IRA","Other investments","HSA"]'::jsonb, '{"stage":"setup","step_number":5,"shown_if":"Always, on this screen."}'::jsonb, '"A list of rows; a tap marks a row \"Yes\"."'::jsonb, '{"file":"game/screens/smart.js","lines":"573","raw":"game/screens/smart.js:573"}'::jsonb, null, '[]'::jsonb, '["setup.acct_each","setup.taxAcctQ"]'::jsonb, null, 460, true, 'Setup', 'Round A: Assets'),
  ('setup.acct_each', 'setup_assets', 'About how much is in it today?', 'range_chips', 'asks', 'live', null, null, null, 'Each account', '["cash_rows","investment_rows","invested_total","cushion_months"]'::jsonb, '["player"]'::jsonb, '["range chips for the kind of account","I know it (type the amount)"]'::jsonb, '{"stage":"setup","step_number":6,"shown_if":"Once for each account the player tapped."}'::jsonb, '"Range chips (Close), or one box to type (Exact). One account at a time, with a breadcrumb."'::jsonb, '{"file":"game/features/amounts.js","lines":"642","raw":"game/features/amounts.js:642"}'::jsonb, null, '["setup.accts"]'::jsonb, '["calc.derive"]'::jsonb, null, 470, true, 'Setup', 'Round A: Assets'),
