  ('setup.income_freq', 'setup_income', 'How often does it come in?', 'tap_single', 'asks', 'live', null, null, null, 'Each source of money', '["income_rhythms","pay_rhythm"]'::jsonb, '["player"]'::jsonb, '["Weekly","Every 2 weeks","Twice a month","Monthly","Paid by the shift or gig"]'::jsonb, '{"stage":"setup","step_number":9,"shown_if":"Once for each kind of income tapped in \"What money comes in?\"."}'::jsonb, '"Chips, once for each source of money."'::jsonb, '{"file":"game/features/amounts.js","lines":"674","raw":"game/features/amounts.js:674"}'::jsonb, null, '["setup.incKinds"]'::jsonb, '["setup.income_amt"]'::jsonb, 'There is no "Daily" chip here. "Daily" exists only in the editor of an income row on My Money (PF_O).', 490, true, 'Setup', 'Round I: Income'),
