  ('takeout.tko.roth', 'retirement', 'How much of your Roth is money you put in?', 'tap_single', 'asks', 'live', null, 'The money you put into a Roth, not its growth. You can take deposits out at any age with no tax. The growth waits until 59 and a half.', 'The rest is growth. Form 5498 of each year shows what you put in.', 'Taking money out', '["x_tko"]'::jsonb, '["player"]'::jsonb, null, '{"stage":"any","step_number":null,"shown_if":"cant_tell"}'::jsonb, '"kitAsk: preset chips, then Guess / Close / Exact as three buttons. Stored as c.x.tko.roth = { v, cf }."'::jsonb, '{"file":"game/features/takeout.js","lines":"147","raw":"game/features/takeout.js:147"}'::jsonb, null, '[]'::jsonb, '[]'::jsonb, null, 3500, true, 'Menu', 'Plans and what-ifs')
