  ('takeout.tko.size', 'retirement', 'People on the plan', 'tap_single', 'asks', 'live', null, 'The people in your tax household. The poverty line goes up with each person.', null, 'Taking money out', '["x_tko"]'::jsonb, '["player"]'::jsonb, null, '{"stage":"any","step_number":null,"shown_if":"cant_tell"}'::jsonb, '"kitAsk: preset chips, then Guess / Close / Exact as three buttons. Stored as c.x.tko.size = { v, cf }."'::jsonb, '{"file":"game/features/takeout.js","lines":"848","raw":"game/features/takeout.js:848"}'::jsonb, null, '[]'::jsonb, '[]'::jsonb, null, 3520, true, 'Menu', 'Plans and what-ifs'),
  ('takeout.tko.conv', 'retirement', 'Roth conversion each year', 'tap_single', 'asks', 'live', null, 'Moving pre-tax money into a Roth. You pay income tax on it that year. Five years later you can take that amount out with no tax. One conversion each year makes a ladder.', null, 'Taking money out', '["x_tko"]'::jsonb, '["player"]'::jsonb, null, '{"stage":"any","step_number":null,"shown_if":"cant_tell"}'::jsonb, '"kitAsk: preset chips, then Guess / Close / Exact as three buttons, and \"Type the exact number\" (a keypad on screen). Stored as c.x.tko.conv = { v, cf }."'::jsonb, '{"file":"game/features/takeout.js","lines":"857","raw":"game/features/takeout.js:857"}'::jsonb, null, '[]'::jsonb, '[]'::jsonb, null, 3530, true, 'Menu', 'Plans and what-ifs'),
  ('takeout.tko.other', 'retirement', 'Other taxable income each year', 'tap_single', 'asks', 'live', null, 'The income the marketplace counts: pay, pensions, interest, gains and Roth conversions. Money from cash or Roth deposits does not count.', 'Part-time pay, a pension, interest. Money from cash or Roth deposits does not count.', 'Taking money out', '["x_tko"]'::jsonb, '["player"]'::jsonb, null, '{"stage":"any","step_number":null,"shown_if":"cant_tell"}'::jsonb, '"kitAsk: preset chips, then Guess / Close / Exact as three buttons, and \"Type the exact number\" (a keypad on screen). Stored as c.x.tko.other = { v, cf }."'::jsonb, '{"file":"game/features/takeout.js","lines":"858","raw":"game/features/takeout.js:858"}'::jsonb, null, '[]'::jsonb, '[]'::jsonb, null, 3540, true, 'Menu', 'Plans and what-ifs'),
  ('taxview.taxv.filing', 'investing_taxes', 'How do you file?', 'tap_single', 'asks', 'live', null, 'How you file your tax return: single, married filing together, or head of household (single with a dependent at home).', null, 'Your tax view', '["x_taxv"]'::jsonb, '["player"]'::jsonb, null, '{"stage":"any","step_number":null,"shown_if":"cant_tell"}'::jsonb, '"kitAsk: preset chips, then Guess / Close / Exact as three buttons. Stored as c.x.taxv.filing = { v, cf }."'::jsonb, '{"file":"game/features/taxview.js","lines":"204","raw":"game/features/taxview.js:204"}'::jsonb, null, '[]'::jsonb, '[]'::jsonb, null, 3550, true, 'Menu', 'Tools and calculators'),
  ('taxview.taxv.gross', 'investing_taxes', 'Pay before taxes, a year', 'tap_single', 'asks', 'live', null, 'What you earn before tax and anything else comes out of your paycheck.', 'The top line of a pay stub, times the paychecks in a year.', 'Your tax view', '["x_taxv"]'::jsonb, '["player"]'::jsonb, null, '{"stage":"any","step_number":null,"shown_if":"cant_tell"}'::jsonb, '"kitAsk: preset chips, then Guess / Close / Exact as three buttons, and \"Type the exact number\" (a keypad on screen). Stored as c.x.taxv.gross = { v, cf }."'::jsonb, '{"file":"game/features/taxview.js","lines":"205","raw":"game/features/taxview.js:205"}'::jsonb, null, '[]'::jsonb, '[]'::jsonb, null, 3560, true, 'Menu', 'Tools and calculators'),
  ('taxview.taxv.pre', 'investing_taxes', 'Pre-tax contributions, a month', 'tap_single', 'asks', 'live', null, 'Money that goes into a plan at work before tax is taken. It lowers your tax this year. You pay tax when you take it out.', 'What goes into a plan at work before your pay lands.', 'Your tax view', '["x_taxv"]'::jsonb, '["player"]'::jsonb, null, '{"stage":"any","step_number":null,"shown_if":"cant_tell"}'::jsonb, '"kitAsk: preset chips, then Guess / Close / Exact as three buttons, and \"Type the exact number\" (a keypad on screen). Stored as c.x.taxv.pre = { v, cf }."'::jsonb, '{"file":"game/features/taxview.js","lines":"214","raw":"game/features/taxview.js:214"}'::jsonb, null, '[]'::jsonb, '[]'::jsonb, null, 3570, true, 'Menu', 'Tools and calculators'),
