  ('vault.vault.score', 'card_plan', 'Your credit score', 'tap_single', 'asks', 'live', null, 'A number from 300 to 850 that lenders use. Most cards with a welcome offer look for 670 or more.', null, 'Card vault', '["x_vault"]'::jsonb, '["player"]'::jsonb, null, '{"stage":"any","step_number":null,"shown_if":"cant_tell"}'::jsonb, '"kitAsk: preset chips, then Guess / Close / Exact as three buttons. Stored as c.x.vault.score = { v, cf }."'::jsonb, '{"file":"game/features/vault.js","lines":"573","raw":"game/features/vault.js:573"}'::jsonb, null, '[]'::jsonb, '[]'::jsonb, null, 3610, true, 'Menu', 'My money'),
  ('vault.vault.spend', 'card_plan', 'How much can you put on a card each month?', 'tap_single', 'asks', 'live', null, 'The part of your monthly spending that a card can pay for: food, getting around, bills, fun. Rent or a mortgage is usually not paid by card.', 'The game starts from your budget: ', 'Card vault', '["x_vault"]'::jsonb, '["player"]'::jsonb, null, '{"stage":"any","step_number":null,"shown_if":"cant_tell"}'::jsonb, '"kitAsk: preset chips, then Guess / Close / Exact as three buttons, and \"Type the exact number\" (a keypad on screen). Stored as c.x.vault.spend = { v, cf }."'::jsonb, '{"file":"game/features/vault.js","lines":"577","raw":"game/features/vault.js:577"}'::jsonb, null, '[]'::jsonb, '[]'::jsonb, null, 3620, true, 'Menu', 'My money'),
  ('vault.vault.programs', 'card_plan', 'Count airline and hotel points too?', 'tap_single', 'asks', 'live', null, 'Points that only one airline or hotel takes. They are worth something only when you would fly or stay with that company.', null, 'Card vault', '["x_vault"]'::jsonb, '["player"]'::jsonb, '["No, cash and bank points only","Yes, I would use them"]'::jsonb, '{"stage":"any","step_number":null,"shown_if":"cant_tell"}'::jsonb, '"kitAsk: preset chips, then Guess / Close / Exact as three buttons. Stored as c.x.vault.programs = { v, cf }."'::jsonb, '{"file":"game/features/vault.js","lines":"590","raw":"game/features/vault.js:590"}'::jsonb, null, '[]'::jsonb, '[]'::jsonb, null, 3630, true, 'Menu', 'My money'),
