  ('ways.cmp.leftAge', 'retirement', 'At what age?', 'tap_single', 'asks', 'live', null, null, 'After that age, this way spends the growth and keeps the amount.', 'Taking money out: Compare the ways', '["x_cmp"]'::jsonb, '["player"]'::jsonb, null, '{"stage":"any","step_number":null,"shown_if":"cant_tell"}'::jsonb, '"kitAsk: preset chips, then Guess / Close / Exact as three buttons. Stored as c.x.cmp.leftAge = { v, cf }."'::jsonb, '{"file":"game/features/ways.js","lines":"411","raw":"game/features/ways.js:411"}'::jsonb, null, '[]'::jsonb, '[]'::jsonb, null, 3680, true, 'Menu', 'Plans and what-ifs'),
  ('ways.odds.stock', 'retirement', 'How much of your money is in stocks?', 'tap_single', 'asks', 'live', null, 'How much of your invested money is in stocks. Stocks grow more over long stretches and fall harder in bad years.', 'The rest is in bonds. The same answer as on Retirement odds.', 'Taking money out: Compare the ways', '["x_odds"]'::jsonb, '["player"]'::jsonb, null, '{"stage":"any","step_number":null,"shown_if":"cant_tell"}'::jsonb, '"kitAsk: preset chips, then Guess / Close / Exact as three buttons. Stored as c.x.odds.stock = { v, cf }."'::jsonb, '{"file":"game/features/ways.js","lines":"428","raw":"game/features/ways.js:428"}'::jsonb, null, '[]'::jsonb, '[]'::jsonb, null, 3690, true, 'Menu', 'Plans and what-ifs'),
  ('windfall.wind.amt', 'investing_taxes', 'How much is it?', 'tap_single', 'asks', 'live', null, 'Money outside your normal pay: a bonus, a gift, a tax refund, an inheritance, a sale.', null, 'Got extra money?', '["x_wind"]'::jsonb, '["player"]'::jsonb, null, '{"stage":"any","step_number":null,"shown_if":"cant_tell"}'::jsonb, '"kitAsk: preset chips, then Guess / Close / Exact as three buttons, and \"Type the exact number\" (a keypad on screen). Stored as c.x.wind.amt = { v, cf }."'::jsonb, '{"file":"game/features/windfall.js","lines":"257","raw":"game/features/windfall.js:257"}'::jsonb, null, '[]'::jsonb, '[]'::jsonb, null, 3700, true, 'Menu', 'Plans and what-ifs'),
  ('windfall.wind.taxed', 'investing_taxes', 'Did tax come out of it?', 'tap_single', 'asks', 'live', null, 'A bonus on a paycheck already had tax taken out. A gift is not taxed to the person who gets it. Freelance pay and most sales have no tax taken out, so part of the money is not yours yet.', 'A bonus on a paycheck: tax came out. A gift: none is owed by you. Freelance pay or a sale: no tax came out yet.', 'Got extra money?', '["x_wind"]'::jsonb, '["player"]'::jsonb, null, '{"stage":"any","step_number":null,"shown_if":"cant_tell"}'::jsonb, '"kitAsk: preset chips, then Guess / Close / Exact as three buttons. Stored as c.x.wind.taxed = { v, cf }."'::jsonb, '{"file":"game/features/windfall.js","lines":"269","raw":"game/features/windfall.js:269"}'::jsonb, null, '[]'::jsonb, '[]'::jsonb, null, 3710, true, 'Menu', 'Plans and what-ifs'),
  ('windfall.wind.fun', 'investing_taxes', 'A share for fun, before the order starts?', 'tap_single', 'asks', 'live', null, 'A share of extra money to enjoy with no strings. It comes out after tax and before the order starts. It opens when your full cushion is in place and no high-interest debt is left.', null, 'Got extra money?', '["x_wind"]'::jsonb, '["player"]'::jsonb, null, '{"stage":"any","step_number":null,"shown_if":"cant_tell"}'::jsonb, '"kitAsk: preset chips, then Guess / Close / Exact as three buttons. Stored as c.x.wind.fun = { v, cf }."'::jsonb, '{"file":"game/features/windfall.js","lines":"273","raw":"game/features/windfall.js:273"}'::jsonb, null, '[]'::jsonb, '[]'::jsonb, null, 3720, true, 'Menu', 'Plans and what-ifs'),
