  ('windfall.tile.start_here', 'investing_taxes', 'Start here', 'computed', 'shows', 'live', 'low', 'The same steps as your plan: a small cushion, the free money from your job, expensive debt, the full cushion, then the tax-favored accounts, then a regular account.', null, 'Got extra money?', '[]'::jsonb, '["player"]'::jsonb, null, '{"stage":"any","step_number":null,"shown_if":"cant_tell"}'::jsonb, '"A tile with one big number and a Guess / Close / Exact pill."'::jsonb, '{"file":"game/features/windfall.js","lines":"280","raw":"game/features/windfall.js:280"}'::jsonb, '"cant_tell"'::jsonb, '[]'::jsonb, '[]'::jsonb, 'Found by a scan for kitTile("label", ...). Inputs and the missing state were not read.', 6650, true, 'Menu', 'Plans and what-ifs'),
