  ('me.tough', 'me_settings', 'Tough love', 'toggle', 'asks', 'live', null, null, 'When you log spending, it shows what that money would have grown to, and what date it moved.', null, '["tough_love"]'::jsonb, '["player"]'::jsonb, '["Off","On"]'::jsonb, '{"stage":"any","step_number":null,"shown_if":"Always, on this screen."}'::jsonb, '"On / Off."'::jsonb, '{"file":"game/screens/ui.js","lines":"5934","raw":"game/screens/ui.js:5934"}'::jsonb, null, '[]'::jsonb, '[]'::jsonb, null, 6700, true, 'Me', 'How the game talks to you'),
  ('me.rival', 'me_settings', 'Rival · someone you can catch', 'tap_single', 'asks', 'live', 'low', null, 'Someone who started the same day you did, from the same spot: a made-up person or a typical path, never a real one. Pick how hard.', null, '[]'::jsonb, '["player"]'::jsonb, '["Coasting Casey","Everyday Riley","Steady Jordan","Relentless Morgan","Trust-fund Taylor","A typical path"]'::jsonb, '{"stage":"any","step_number":null,"shown_if":"Always, on this screen."}'::jsonb, '"Chips: pick how hard."'::jsonb, '{"file":"game/screens/ui.js","lines":"5054","raw":"game/screens/ui.js:5054"}'::jsonb, null, '[]'::jsonb, '[]'::jsonb, 'Where the pick is stored was not read.', 6710, true, 'Me', 'Role model and rival'),
  ('plan.view', 'next_steps', 'Today / This week / Month / Year', 'tap_single', 'asks', 'live', null, null, null, null, '["planner_tasks"]'::jsonb, '["player"]'::jsonb, '["Today","This week","Month","Year"]'::jsonb, '{"stage":"any","step_number":null,"shown_if":"Always, on this screen."}'::jsonb, '"Four buttons at the top of the tab."'::jsonb, '{"file":"game/screens/planner.js","lines":"482","raw":"game/screens/planner.js:482"}'::jsonb, null, '[]'::jsonb, '[]'::jsonb, null, 6720, true, 'Next Steps', 'View switch'),
