  ('plan.task_state', 'next_steps', '✓ Done / Working on it / Waiting on someone / Doesn''t apply', 'tap_single', 'asks', 'live', null, null, null, null, '["planner_tasks","not_applicable"]'::jsonb, '["player"]'::jsonb, '["✓ Done (It''s handled)","Working on it (Keep it on my list)","Waiting on someone (I''ll check back)","Doesn''t apply (Not for me)"]'::jsonb, '{"stage":"any","step_number":null,"shown_if":"Always, on this screen."}'::jsonb, '"Four buttons at the top of the sheet of one task (\"Plan it\" / \"Update\")."'::jsonb, '{"file":"game/screens/planner.js","lines":"584","raw":"game/screens/planner.js:584"}'::jsonb, null, '[]'::jsonb, '["tab.plan"]'::jsonb, null, 6740, true, 'Next Steps', 'One task'),
  ('plan.already', 'your_path', 'Already done / Not yet (on a step of the path)', 'tap_single', 'asks', 'live', null, null, null, null, '["era_step_ranks","parked"]'::jsonb, '["player"]'::jsonb, '["Do it","Already done","Not yet"]'::jsonb, '{"stage":"any","step_number":null,"shown_if":"Always, on this screen."}'::jsonb, '"Three buttons on each step of the path. On the sheet of a step the same shortcut reads \"I already did this\"."'::jsonb, '{"file":"game/screens/ui.js","lines":"1502","raw":"game/screens/ui.js:1502"}'::jsonb, null, '[]'::jsonb, '[]'::jsonb, null, 6750, true, 'Home', 'Your path'),
