  ('ask.take', 'money_lists', 'Money coming in (one small question at a time)', 'range_chips', 'asks', 'live', 'low', 'So the game knows how much money you have to work with each month.', 'Count what lands in your bank. That is after taxes come out.', 'Money coming in', '["income_rows","take_home"]'::jsonb, '["player"]'::jsonb, null, '{"stage":"any","step_number":null,"shown_if":"Always, on this screen."}'::jsonb, '"One small question on screen: a count first, then each amount by range chips or a typed number. The words of the question are built in code."'::jsonb, '{"file":"game/data/askwords.js","lines":"17","raw":"game/data/askwords.js:17"}'::jsonb, null, '[]'::jsonb, '["calc.derive"]'::jsonb, 'why is the line "why the game asks" of data/askwords.js, shown with the question.', 6930, true, 'My Money', 'Make your numbers real'),
