  ('ask.cash', 'money_lists', 'Cash you can reach (one small question at a time)', 'range_chips', 'asks', 'live', 'low', 'This is the money that keeps you safe when something goes wrong.', 'Only money you could use this week.', 'Cash you can reach', '["cash_rows"]'::jsonb, '["player"]'::jsonb, null, '{"stage":"any","step_number":null,"shown_if":"Always, on this screen."}'::jsonb, '"One small question on screen: a count first, then each amount by range chips or a typed number. The words of the question are built in code."'::jsonb, '{"file":"game/data/askwords.js","lines":"35","raw":"game/data/askwords.js:35"}'::jsonb, null, '[]'::jsonb, '["calc.derive"]'::jsonb, 'why is the line "why the game asks" of data/askwords.js, shown with the question.', 6950, true, 'My Money', 'Make your numbers real'),
  ('ask.inv', 'money_lists', 'What you have invested (one small question at a time)', 'range_chips', 'asks', 'live', 'low', 'So the game can show how close you are to not needing a paycheck.', 'Investing means money you put away to grow for later.', 'What you have invested', '["investment_rows"]'::jsonb, '["player"]'::jsonb, null, '{"stage":"any","step_number":null,"shown_if":"Always, on this screen."}'::jsonb, '"One small question on screen: a count first, then each amount by range chips or a typed number. The words of the question are built in code."'::jsonb, '{"file":"game/data/askwords.js","lines":"44","raw":"game/data/askwords.js:44"}'::jsonb, null, '[]'::jsonb, '["calc.derive"]'::jsonb, 'why is the line "why the game asks" of data/askwords.js, shown with the question.', 6960, true, 'My Money', 'Make your numbers real'),
  ('ask.debt', 'money_lists', 'What you owe (one small question at a time)', 'range_chips', 'asks', 'live', 'low', 'So the game can show which debt costs you the most, and which one to pay first.', 'The whole amount left to pay back. Not the monthly payment.', 'What you owe', '["debt_rows"]'::jsonb, '["player"]'::jsonb, null, '{"stage":"any","step_number":null,"shown_if":"Always, on this screen."}'::jsonb, '"One small question on screen: a count first, then each amount by range chips or a typed number. The words of the question are built in code."'::jsonb, '{"file":"game/data/askwords.js","lines":"53","raw":"game/data/askwords.js:53"}'::jsonb, null, '[]'::jsonb, '["calc.derive"]'::jsonb, 'why is the line "why the game asks" of data/askwords.js, shown with the question.', 6970, true, 'My Money', 'Make your numbers real'),
  ('askdb.apr', 'debt_plan', 'What yearly rate does this debt charge?', 'range_chips', 'asks', 'live', 'low', 'The rate decides which debt costs you the most every month.', 'When you borrow money, you pay back extra. The extra is called interest. The yearly rate is a percent, and bills call it APR.', 'One small question at a time', '["debt_rows"]'::jsonb, '["player"]'::jsonb, null, '{"stage":"any","step_number":null,"shown_if":"Always, on this screen."}'::jsonb, '"One small question on screen, with \"what it means\", \"why the game asks\" and \"where to find it\"."'::jsonb, '{"file":"game/features/ask2.js","lines":"17","raw":"game/features/ask2.js:17"}'::jsonb, null, '[]'::jsonb, '[]'::jsonb, 'why is the line "why the game asks" of features/ask2.js.', 6980, true, 'My Money', 'One debt'),
  ('askdb.pay', 'debt_plan', 'How much do you pay on this each month?', 'range_chips', 'asks', 'live', 'low', 'So the game can tell you the month this debt will be gone.', 'The amount you send every month. If it changes, use what you sent last month.', 'One small question at a time', '["debt_rows"]'::jsonb, '["player"]'::jsonb, null, '{"stage":"any","step_number":null,"shown_if":"Always, on this screen."}'::jsonb, '"One small question on screen, with \"what it means\", \"why the game asks\" and \"where to find it\"."'::jsonb, '{"file":"game/features/ask2.js","lines":"24","raw":"game/features/ask2.js:24"}'::jsonb, null, '[]'::jsonb, '[]'::jsonb, 'why is the line "why the game asks" of features/ask2.js.', 6990, true, 'My Money', 'One debt'),
  ('askdb.lim', 'debt_plan', 'What is the most this card lets you borrow?', 'range_chips', 'asks', 'live', 'low', 'Using only a small part of your limit helps your credit score. The game works out how much you use.', 'That number is called the credit limit.', 'One small question at a time', '["debt_rows"]'::jsonb, '["player"]'::jsonb, null, '{"stage":"any","step_number":null,"shown_if":"Always, on this screen."}'::jsonb, '"One small question on screen, with \"what it means\", \"why the game asks\" and \"where to find it\"."'::jsonb, '{"file":"game/features/ask2.js","lines":"31","raw":"game/features/ask2.js:31"}'::jsonb, null, '[]'::jsonb, '[]'::jsonb, 'why is the line "why the game asks" of features/ask2.js.', 7000, true, 'My Money', 'One debt')
