  ('askdb.hassle', 'debt_plan', 'How much does this debt bother you?', 'range_chips', 'asks', 'live', 'low', 'Some people feel better clearing the most annoying debt first. This lets the game build that plan too.', '1 means you barely think about it. 5 means it is on your mind a lot.', 'One small question at a time', '["debt_rows"]'::jsonb, '["player"]'::jsonb, null, '{"stage":"any","step_number":null,"shown_if":"Always, on this screen."}'::jsonb, '"One small question on screen, with \"what it means\", \"why the game asks\" and \"where to find it\"."'::jsonb, '{"file":"game/features/ask2.js","lines":"38","raw":"game/features/ask2.js:38"}'::jsonb, null, '[]'::jsonb, '[]'::jsonb, 'why is the line "why the game asks" of features/ask2.js.', 7010, true, 'My Money', 'One debt'),
  ('askkn.tax', 'key_numbers', 'Out of every $100 you earn, about how many dollars are taken out before you get paid?', 'range_chips', 'asks', 'live', 'low', 'So the game can tell your pay before taxes from the money you really get.', 'Taxes and a few other things come out of your pay before it reaches your bank.', 'One small question at a time', '["key_number_answers"]'::jsonb, '["player"]'::jsonb, null, '{"stage":"any","step_number":null,"shown_if":"Always, on this screen."}'::jsonb, '"One small question on screen, with \"what it means\", \"why the game asks\" and \"where to find it\"."'::jsonb, '{"file":"game/features/ask2.js","lines":"124","raw":"game/features/ask2.js:124"}'::jsonb, null, '[]'::jsonb, '[]'::jsonb, 'why is the line "why the game asks" of features/ask2.js.', 7020, true, 'My Money', 'Key numbers'),
  ('askkn.debtPay', 'key_numbers', 'How much do you pay toward all your debts in one month?', 'range_chips', 'asks', 'live', 'low', 'So the game can show how much of your pay goes to debt.', 'Add up every payment: cards, loans, a car.', 'One small question at a time', '["key_number_answers"]'::jsonb, '["player"]'::jsonb, null, '{"stage":"any","step_number":null,"shown_if":"Always, on this screen."}'::jsonb, '"One small question on screen, with \"what it means\", \"why the game asks\" and \"where to find it\"."'::jsonb, '{"file":"game/features/ask2.js","lines":"131","raw":"game/features/ask2.js:131"}'::jsonb, null, '[]'::jsonb, '[]'::jsonb, 'why is the line "why the game asks" of features/ask2.js.', 7030, true, 'My Money', 'Key numbers'),
  ('askkn.limit', 'key_numbers', 'If you add up the limits on all your cards, what do you get?', 'range_chips', 'asks', 'live', 'low', 'Using a small part of your limits helps your credit score. The game works out how much you use.', 'A card''s limit is the most it lets you borrow.', 'One small question at a time', '["key_number_answers"]'::jsonb, '["player"]'::jsonb, null, '{"stage":"any","step_number":null,"shown_if":"Always, on this screen."}'::jsonb, '"One small question on screen, with \"what it means\", \"why the game asks\" and \"where to find it\"."'::jsonb, '{"file":"game/features/ask2.js","lines":"137","raw":"game/features/ask2.js:137"}'::jsonb, null, '[]'::jsonb, '[]'::jsonb, 'why is the line "why the game asks" of features/ask2.js.', 7040, true, 'My Money', 'Key numbers'),
  ('askkn.pre', 'key_numbers', 'How much of your pay goes into a retirement plan at work each month?', 'range_chips', 'asks', 'live', 'low', 'This is saving you already do. The game should count it.', 'This comes out before your pay lands. No plan at work means $0.', 'One small question at a time', '["key_number_answers"]'::jsonb, '["player"]'::jsonb, null, '{"stage":"any","step_number":null,"shown_if":"Always, on this screen."}'::jsonb, '"One small question on screen, with \"what it means\", \"why the game asks\" and \"where to find it\"."'::jsonb, '{"file":"game/features/ask2.js","lines":"143","raw":"game/features/ask2.js:143"}'::jsonb, null, '[]'::jsonb, '[]'::jsonb, 'why is the line "why the game asks" of features/ask2.js.', 7050, true, 'My Money', 'Key numbers'),
  ('askkn.matchAmt', 'key_numbers', 'How much does your job add to that plan each month?', 'range_chips', 'asks', 'live', 'low', 'A match is free money. The game counts it as part of what you save.', 'Some jobs add money when you do. That is called a match. No match means $0.', 'One small question at a time', '["key_number_answers"]'::jsonb, '["player"]'::jsonb, null, '{"stage":"any","step_number":null,"shown_if":"Always, on this screen."}'::jsonb, '"One small question on screen, with \"what it means\", \"why the game asks\" and \"where to find it\"."'::jsonb, '{"file":"game/features/ask2.js","lines":"149","raw":"game/features/ask2.js:149"}'::jsonb, null, '[]'::jsonb, '[]'::jsonb, 'why is the line "why the game asks" of features/ask2.js.', 7060, true, 'My Money', 'Key numbers'),
  ('askkn.pay1', 'key_numbers', 'About a year ago, how much did you bring home in a month?', 'range_chips', 'asks', 'live', 'low', 'So the game can show whether your pay is growing.', 'Close is fine. From here on the game keeps track for you.', 'One small question at a time', '["key_number_answers"]'::jsonb, '["player"]'::jsonb, null, '{"stage":"any","step_number":null,"shown_if":"Always, on this screen."}'::jsonb, '"One small question on screen, with \"what it means\", \"why the game asks\" and \"where to find it\"."'::jsonb, '{"file":"game/features/ask2.js","lines":"155","raw":"game/features/ask2.js:155"}'::jsonb, null, '[]'::jsonb, '[]'::jsonb, 'why is the line "why the game asks" of features/ask2.js.', 7070, true, 'My Money', 'Key numbers'),
  ('askkn.fee', 'key_numbers', 'What do your investments cost you each year?', 'range_chips', 'asks', 'live', 'low', 'A small fee takes a big bite over many years. The game shows it in dollars.', 'Funds charge a small yearly fee, shown as a percent. An advisor adds their own fee on top.', 'One small question at a time', '["key_number_answers"]'::jsonb, '["player"]'::jsonb, null, '{"stage":"any","step_number":null,"shown_if":"Always, on this screen."}'::jsonb, '"One small question on screen, with \"what it means\", \"why the game asks\" and \"where to find it\"."'::jsonb, '{"file":"game/features/ask2.js","lines":"161","raw":"game/features/ask2.js:161"}'::jsonb, null, '[]'::jsonb, '[]'::jsonb, 'why is the line "why the game asks" of features/ask2.js.', 7080, true, 'My Money', 'Key numbers'),
  ('askkn.carPay', 'key_numbers', 'How much is your car payment each month?', 'range_chips', 'asks', 'live', 'low', 'So the game can compare it to your pay.', 'Only the loan or lease payment. No car payment means $0.', 'One small question at a time', '["key_number_answers"]'::jsonb, '["player"]'::jsonb, null, '{"stage":"any","step_number":null,"shown_if":"Always, on this screen."}'::jsonb, '"One small question on screen, with \"what it means\", \"why the game asks\" and \"where to find it\"."'::jsonb, '{"file":"game/features/ask2.js","lines":"167","raw":"game/features/ask2.js:167"}'::jsonb, null, '[]'::jsonb, '[]'::jsonb, 'why is the line "why the game asks" of features/ask2.js.', 7090, true, 'My Money', 'Key numbers'),
  ('askkn.give', 'key_numbers', 'How much do you give away each month?', 'range_chips', 'asks', 'live', 'low', 'Giving is part of where your money goes. The game shows it as a share of your pay.', 'Charity, tithing, or supporting someone.', 'One small question at a time', '["key_number_answers"]'::jsonb, '["player"]'::jsonb, null, '{"stage":"any","step_number":null,"shown_if":"Always, on this screen."}'::jsonb, '"One small question on screen, with \"what it means\", \"why the game asks\" and \"where to find it\"."'::jsonb, '{"file":"game/features/ask2.js","lines":"173","raw":"game/features/ask2.js:173"}'::jsonb, null, '[]'::jsonb, '[]'::jsonb, 'why is the line "why the game asks" of features/ask2.js.', 7100, true, 'My Money', 'Key numbers'),
  ('asksh.match', 'money_lists', 'Does your job add money to your retirement plan when you do?', 'tap_single', 'asks', 'live', 'low', 'If there is a match you are not getting, that is usually the first money move to make.', 'Some jobs do this. It is called a match, and it is free money.', 'One small question at a time', '["sharp_flags"]'::jsonb, '["player"]'::jsonb, '["Yes, and I get all of it","Yes, but I don''t get all of it","No, my job has no match","I''m not sure"]'::jsonb, '{"stage":"any","step_number":null,"shown_if":"Always, on this screen."}'::jsonb, '"One small question on screen, with \"what it means\", \"why the game asks\" and \"where to find it\"."'::jsonb, '{"file":"game/features/ask2.js","lines":"232","raw":"game/features/ask2.js:232"}'::jsonb, null, '[]'::jsonb, '[]'::jsonb, 'why is the line "why the game asks" of features/ask2.js.', 7110, true, 'My Money', 'Make your numbers real'),
  ('asksh.tax', 'money_lists', 'Do you put money in accounts that lower your taxes?', 'tap_single', 'asks', 'live', 'low', 'The game checks whether this step is done, or still ahead of you.', 'These are a Roth IRA, an HSA, and the retirement plan at work. Money inside them is taxed less, so it grows faster.', 'One small question at a time', '["sharp_flags"]'::jsonb, '["player"]'::jsonb, '["Yes, as much as the rules allow","Yes, some","Not yet"]'::jsonb, '{"stage":"any","step_number":null,"shown_if":"Always, on this screen."}'::jsonb, '"One small question on screen, with \"what it means\", \"why the game asks\" and \"where to find it\"."'::jsonb, '{"file":"game/features/ask2.js","lines":"250","raw":"game/features/ask2.js:250"}'::jsonb, null, '[]'::jsonb, '[]'::jsonb, 'why is the line "why the game asks" of features/ask2.js.', 7120, true, 'My Money', 'Make your numbers real')
